CREATE TABLE IF NOT EXISTS skills (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, `name` VARCHAR(64) NOT NULL, pinned_version_id VARCHAR(36) NULL, retired_at BIGINT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT fk_skills_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE skills ADD CONSTRAINT skill_team_name UNIQUE (team_id, `name`);
CREATE TABLE IF NOT EXISTS skill_versions (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, version VARCHAR(64) NOT NULL, digest VARCHAR(71) NOT NULL, size_bytes BIGINT NOT NULL, file_count INT NOT NULL, published_by VARCHAR(36) NOT NULL, published_at BIGINT NOT NULL, retired_at BIGINT NULL, CONSTRAINT fk_skill_versions_skill_id__id FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE skill_versions ADD CONSTRAINT skill_version_label UNIQUE (skill_id, version);
CREATE TABLE IF NOT EXISTS skill_files (version_id VARCHAR(36), `path` VARCHAR(255), mode VARCHAR(16) NOT NULL, `size` INT NOT NULL, sha256 CHAR(64) NOT NULL, content MEDIUMBLOB NOT NULL, CONSTRAINT pk_skill_files PRIMARY KEY (version_id, `path`), CONSTRAINT fk_skill_files_version_id__id FOREIGN KEY (version_id) REFERENCES skill_versions(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS skill_assignments (skill_id VARCHAR(36), member_id VARCHAR(36), decision VARCHAR(8) NOT NULL, updated_by VARCHAR(36) NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT pk_skill_assignments PRIMARY KEY (skill_id, member_id), CONSTRAINT fk_skill_assignments_skill_id__id FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_skill_assignments_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX skill_assignment_member ON skill_assignments (member_id);
CREATE TABLE IF NOT EXISTS skill_installations (device_id VARCHAR(36), skill_id VARCHAR(36), version VARCHAR(64) NULL, digest VARCHAR(71) NULL, status VARCHAR(16) NOT NULL, reported_at BIGINT NOT NULL, CONSTRAINT pk_skill_installations PRIMARY KEY (device_id, skill_id), CONSTRAINT fk_skill_installations_device_id__id FOREIGN KEY (device_id) REFERENCES devices(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_skill_installations_skill_id__id FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
